INSERT INTO assets(treatment_id,category,type,title,description,payload,reviewer_name,tags,sort_order,staff_note,source_url,source_note,usage_rights,review_status,is_public,is_hidden,updated_at) VALUES(1,'faq','faq','임플란트는 어떤 역할을 하나요?','한 질문에 하나의 설명 · 의료진 검토가 필요한 교육용 초안입니다.','{"question": "임플란트는 어떤 역할을 하나요?", "answer": "임플란트는 빠진 치아를 대신할 인공 치아를 지지하기 위해 턱뼈에 심는 구조물입니다. 모든 경우에 같은 방법을 쓰는 것은 아니며, 잇몸과 뼈 상태·전신 건강 등을 함께 평가해 치료 방법을 정합니다."}','검토 대기','["설명초안", "핵심상담", "flow-draft-01"]',901,'빠진 치아의 위치를 먼저 짚고, 임플란트·브리지·틀니 등 가능한 대안을 개별 진단에 맞게 설명합니다.','https://www.mouthhealthy.org/all-topics-a-z/implants','참고: 미국치과의사협회 ADA MouthHealthy. 2026-09-08 페이지 확인. 한국어 설명은 별도로 작성한 AI 보조 초안이며 원문 인용·공식 번역이 아닙니다. 임상 검토와 최종 사용 권한 확인이 필요합니다.','unconfirmed','draft',1,1,CURRENT_TIMESTAMP);
INSERT INTO assets(treatment_id,category,type,title,description,payload,reviewer_name,tags,sort_order,staff_note,source_url,source_note,usage_rights,review_status,is_public,is_hidden,updated_at) VALUES(1,'faq','faq','임플란트 치료 기간은 왜 사람마다 다른가요?','한 질문에 하나의 설명 · 의료진 검토가 필요한 교육용 초안입니다.','{"question": "임플란트 치료 기간은 왜 사람마다 다른가요?", "answer": "뼈와 임플란트가 안정적으로 결합하는 과정, 뼈 상태, 함께 필요한 치료 등에 따라 일정이 달라집니다. 다른 사람의 치료 기간을 그대로 적용하기보다 검사 결과에 따른 단계와 예상 일정을 확인하는 것이 중요합니다."}','검토 대기','["설명초안", "핵심상담", "flow-draft-02"]',902,'고정 기간이나 성공을 보장하지 않습니다. 이 환자의 계획은 담당 의료진이 별도로 기입합니다.','https://www.mouthhealthy.org/all-topics-a-z/implants','참고: 미국치과의사협회 ADA MouthHealthy. 2026-09-08 페이지 확인. 한국어 설명은 별도로 작성한 AI 보조 초안이며 원문 인용·공식 번역이 아닙니다. 임상 검토와 최종 사용 권한 확인이 필요합니다.','unconfirmed','draft',1,1,CURRENT_TIMESTAMP);
INSERT INTO assets(treatment_id,category,type,title,description,payload,reviewer_name,tags,sort_order,staff_note,source_url,source_note,usage_rights,review_status,is_public,is_hidden,updated_at) VALUES(1,'faq','faq','임플란트 상담 전에 어떤 내용을 알려야 하나요?','한 질문에 하나의 설명 · 의료진 검토가 필요한 교육용 초안입니다.','{"question": "임플란트 상담 전에 어떤 내용을 알려야 하나요?", "answer": "전신 질환, 복용 중인 약, 흡연 여부와 이전 치료 경험은 치료 계획을 세우는 데 참고가 됩니다. 약을 임의로 중단하지 말고 의료진에게 현재 상태를 알려 주세요."}','검토 대기','["설명초안", "핵심상담", "flow-draft-03"]',903,'병력·복용약 확인은 별도 의료 기록에서 진행합니다. 이 안내장에 민감한 세부 병력을 복사하지 않습니다.','https://www.mouthhealthy.org/all-topics-a-z/implants','참고: 미국치과의사협회 ADA MouthHealthy. 2026-09-08 페이지 확인. 한국어 설명은 별도로 작성한 AI 보조 초안이며 원문 인용·공식 번역이 아닙니다. 임상 검토와 최종 사용 권한 확인이 필요합니다.','unconfirmed','draft',1,1,CURRENT_TIMESTAMP);
INSERT INTO assets(treatment_id,category,type,title,description,payload,reviewer_name,tags,sort_order,staff_note,source_url,source_note,usage_rights,review_status,is_public,is_hidden,updated_at) VALUES(4,'faq','faq','신경치료는 왜 필요한가요?','한 질문에 하나의 설명 · 의료진 검토가 필요한 교육용 초안입니다.','{"question": "신경치료는 왜 필요한가요?", "answer": "치아 내부의 치수가 깊은 충치나 손상 등으로 문제가 생긴 경우, 감염되거나 손상된 조직을 제거하고 내부를 치료하여 치아를 보존하는 방법을 고려할 수 있습니다. 필요 여부는 증상과 검사를 종합해 판단합니다."}','검토 대기','["설명초안", "핵심상담", "flow-draft-04"]',904,'통증만으로 진단을 단정하지 않고 검사 결과와 보존 가능성을 연결해 설명합니다.','https://www.mouthhealthy.org/all-topics-a-z/root-canals','참고: 미국치과의사협회 ADA MouthHealthy. 2026-09-08 페이지 확인. 한국어 설명은 별도로 작성한 AI 보조 초안이며 원문 인용·공식 번역이 아닙니다. 임상 검토와 최종 사용 권한 확인이 필요합니다.','unconfirmed','draft',1,1,CURRENT_TIMESTAMP);
INSERT INTO assets(treatment_id,category,type,title,description,payload,reviewer_name,tags,sort_order,staff_note,source_url,source_note,usage_rights,review_status,is_public,is_hidden,updated_at) VALUES(4,'faq','faq','신경치료와 발치는 어떻게 다른가요?','한 질문에 하나의 설명 · 의료진 검토가 필요한 교육용 초안입니다.','{"question": "신경치료와 발치는 어떻게 다른가요?", "answer": "신경치료는 치아를 보존하기 위한 치료이고, 발치는 치아를 제거하는 치료입니다. 치아를 유지할 수 있는 상태인지, 주변 조직에 어떤 문제가 있는지에 따라 가능한 선택이 달라집니다."}','검토 대기','["설명초안", "핵심상담", "flow-draft-05"]',905,'어떤 치료가 무조건 더 낫다는 설명 대신 환자의 진단·예후·대안을 확인합니다.','https://www.mouthhealthy.org/all-topics-a-z/root-canals','참고: 미국치과의사협회 ADA MouthHealthy. 2026-09-08 페이지 확인. 한국어 설명은 별도로 작성한 AI 보조 초안이며 원문 인용·공식 번역이 아닙니다. 임상 검토와 최종 사용 권한 확인이 필요합니다.','unconfirmed','draft',1,1,CURRENT_TIMESTAMP);
INSERT INTO assets(treatment_id,category,type,title,description,payload,reviewer_name,tags,sort_order,staff_note,source_url,source_note,usage_rights,review_status,is_public,is_hidden,updated_at) VALUES(4,'faq','faq','신경치료 뒤에도 치아를 보호하는 치료가 필요한가요?','한 질문에 하나의 설명 · 의료진 검토가 필요한 교육용 초안입니다.','{"question": "신경치료 뒤에도 치아를 보호하는 치료가 필요한가요?", "answer": "치아 내부를 치료한 뒤에도 남은 치아를 보호하고 기능을 회복하기 위한 수복 치료가 필요할 수 있습니다. 충전이나 크라운 등 어떤 방법을 사용할지는 남아 있는 치아의 상태에 따라 달라집니다."}','검토 대기','["설명초안", "핵심상담", "flow-draft-06"]',906,'모든 치아에 같은 수복을 권하지 않습니다. 치료 후 계획을 개별 안내합니다.','https://www.mouthhealthy.org/all-topics-a-z/root-canals','참고: 미국치과의사협회 ADA MouthHealthy. 2026-09-08 페이지 확인. 한국어 설명은 별도로 작성한 AI 보조 초안이며 원문 인용·공식 번역이 아닙니다. 임상 검토와 최종 사용 권한 확인이 필요합니다.','unconfirmed','draft',1,1,CURRENT_TIMESTAMP);
INSERT INTO assets(treatment_id,category,type,title,description,payload,reviewer_name,tags,sort_order,staff_note,source_url,source_note,usage_rights,review_status,is_public,is_hidden,updated_at) VALUES(5,'faq','faq','양치할 때 잇몸에서 피가 나면 무엇을 확인하나요?','한 질문에 하나의 설명 · 의료진 검토가 필요한 교육용 초안입니다.','{"question": "양치할 때 잇몸에서 피가 나면 무엇을 확인하나요?", "answer": "잇몸 출혈은 잇몸 상태를 확인해야 하는 신호 중 하나입니다. 출혈만으로 원인을 단정할 수 없으므로 반복되거나 다른 불편이 동반되면 치과에서 확인받는 것이 좋습니다."}','검토 대기','["설명초안", "핵심상담", "flow-draft-07"]',907,'출혈 원인을 단정하거나 사진 한 장으로 진단하지 않습니다. 문진과 검사의 필요성을 설명합니다.','https://www.mouthhealthy.org/all-topics-a-z/gum-disease','참고: 미국치과의사협회 ADA MouthHealthy. 2026-09-08 페이지 확인. 한국어 설명은 별도로 작성한 AI 보조 초안이며 원문 인용·공식 번역이 아닙니다. 임상 검토와 최종 사용 권한 확인이 필요합니다.','unconfirmed','draft',1,1,CURRENT_TIMESTAMP);
INSERT INTO assets(treatment_id,category,type,title,description,payload,reviewer_name,tags,sort_order,staff_note,source_url,source_note,usage_rights,review_status,is_public,is_hidden,updated_at) VALUES(5,'faq','faq','아프지 않아도 잇몸 검사가 필요한가요?','한 질문에 하나의 설명 · 의료진 검토가 필요한 교육용 초안입니다.','{"question": "아프지 않아도 잇몸 검사가 필요한가요?", "answer": "잇몸 질환은 뚜렷한 통증 없이 진행될 수 있습니다. 통증 유무만으로 건강 상태를 판단하기보다는 잇몸과 치아를 지지하는 조직을 정기적으로 확인하는 것이 중요합니다."}','검토 대기','["설명초안", "핵심상담", "flow-draft-08"]',908,'통증이 없다는 말에 불안을 과도하게 유발하지 않도록 현재 검사 소견을 함께 설명합니다.','https://www.mouthhealthy.org/all-topics-a-z/gum-disease','참고: 미국치과의사협회 ADA MouthHealthy. 2026-09-08 페이지 확인. 한국어 설명은 별도로 작성한 AI 보조 초안이며 원문 인용·공식 번역이 아닙니다. 임상 검토와 최종 사용 권한 확인이 필요합니다.','unconfirmed','draft',1,1,CURRENT_TIMESTAMP);
INSERT INTO assets(treatment_id,category,type,title,description,payload,reviewer_name,tags,sort_order,staff_note,source_url,source_note,usage_rights,review_status,is_public,is_hidden,updated_at) VALUES(5,'faq','faq','집에서 관리하는 것과 치과에서 받는 관리는 어떻게 다른가요?','한 질문에 하나의 설명 · 의료진 검토가 필요한 교육용 초안입니다.','{"question": "집에서 관리하는 것과 치과에서 받는 관리는 어떻게 다른가요?", "answer": "매일 하는 양치와 치아 사이 청소는 기본 관리입니다. 이미 생긴 잇몸 문제의 상태를 평가하고 필요한 전문적인 처치를 결정하는 일은 치과 검사를 통해 이루어집니다. 두 관리는 서로를 대신하기보다 함께 이루어집니다."}','검토 대기','["설명초안", "핵심상담", "flow-draft-09"]',909,'도구·방법은 환자의 손 사용 능력과 구강 상태에 맞춰 직접 확인합니다.','https://www.mouthhealthy.org/all-topics-a-z/gum-disease','참고: 미국치과의사협회 ADA MouthHealthy. 2026-09-08 페이지 확인. 한국어 설명은 별도로 작성한 AI 보조 초안이며 원문 인용·공식 번역이 아닙니다. 임상 검토와 최종 사용 권한 확인이 필요합니다.','unconfirmed','draft',1,1,CURRENT_TIMESTAMP);
INSERT INTO assets(treatment_id,category,type,title,description,payload,reviewer_name,tags,sort_order,staff_note,source_url,source_note,usage_rights,review_status,is_public,is_hidden,updated_at) VALUES(5,'faq','faq','잇몸 치료 후에도 다시 확인해야 하나요?','한 질문에 하나의 설명 · 의료진 검토가 필요한 교육용 초안입니다.','{"question": "잇몸 치료 후에도 다시 확인해야 하나요?", "answer": "치료 후에도 집에서의 관리와 병원에서의 확인이 이어질 필요가 있습니다. 다음 확인 시점은 현재 잇몸 상태와 관리 상황에 따라 달라질 수 있으므로 담당 의료진이 안내한 일정을 확인해 주세요."}','검토 대기','["설명초안", "핵심상담", "flow-draft-10"]',910,'일률적인 재내원 주기를 약속하지 않습니다. 환자별 다음 일정은 별도 메모로 안내합니다.','https://www.mouthhealthy.org/all-topics-a-z/gum-disease','참고: 미국치과의사협회 ADA MouthHealthy. 2026-09-08 페이지 확인. 한국어 설명은 별도로 작성한 AI 보조 초안이며 원문 인용·공식 번역이 아닙니다. 임상 검토와 최종 사용 권한 확인이 필요합니다.','unconfirmed','draft',1,1,CURRENT_TIMESTAMP);
